import puppeteer from "puppeteer";
import { createWriteStream, readFileSync } from "fs"
import { promisify } from "util";

import { sportNameMap } from "../sportNameMap.js";
import { tournamentNameMap } from "../tournamentName/CS2/Map.js";
import { marketNameMap } from "../marketNameMap.js";
import { stripTeamName } from "../util/stripTeamName.js";

// generated by chatGPT https://chatgpt.com/c/a9300588-42f8-40ee-bff4-b00c945cee1e
function convDatetimeToISO(dateStr){

  const parseDateStr = (dateStr) => {
    const [monthDay, time] = dateStr.split(', ');
    const [month, day] = monthDay.split(' ');
    const [hours, minutes] = time.split(':');
  
    const date = new Date();
    date.setMonth(new Date(`${month} 1`).getMonth()); // Get the month index
    date.setDate(parseInt(day));
    date.setHours(parseInt(hours));
    date.setMinutes(parseInt(minutes));
    date.setSeconds(0);
    date.setMilliseconds(0);
  
    return date;
  };
  
  const date = parseDateStr(dateStr);
  
  // Format the date as ISO 8601
  return date.toISOString();
  
}

export async function scrapeMatchURL_tp(data, url){
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ["--disable-web-security"]
  });  

  const bookAbbrev = 'tp';
  // open a file for logging
  const logFilePath = `./books/${bookAbbrev}/log.txt`
  const log = createWriteStream(logFilePath, {flags: 'a'}); 

  // load the book-specific mappings from json files
  const sportNameMappingPath = `books/${bookAbbrev}/sportNameMapping.json`;
  let sportNameMapping;
  try{
    sportNameMapping = Object.freeze(JSON.parse(readFileSync(sportNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${sportNameMappingPath}\n`);
  }
  const tournamentNameMappingPath = `books/${bookAbbrev}/tournamentNameMapping.json`;
  let tournamentNameMapping;
  try{
    tournamentNameMapping = Object.freeze(JSON.parse(readFileSync(tournamentNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${tournamentNameMappingPath}\n`);
  }
  const marketNameMappingPath = `books/${bookAbbrev}/marketNameMapping.json`;
  let marketNameMapping;
  try{
    marketNameMapping = Object.freeze(JSON.parse(readFileSync(marketNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${marketNameMappingPath}\n`);
  }


  try{
//    console.log('data: ');
//    console.log(JSON.stringify(data, null, 2));
    const page = await browser.newPage();    
    await page.setViewport({width:1920, height:30000})
    await page.goto(url);
  
    let selector, el, mapping;
    // get sport
    selector = "#breadcrumbs > div:nth-child(2) > a";
    el = await page.waitForSelector(selector);
    let sportName = await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el);
    mapping = sportNameMapping.mapping.find( m => m.specificName === sportName);
    if(mapping){
      sportName = sportNameMap[mapping.globalID];
    } else{
      log.write(`Failure! sportName Mapping of '${sportName}' does not exist in ${sportNameMappingPath}\n`);
      return;
    }
//    console.log('>>>>>>>>>>>>>>> scraped sportName: ' + sportName);
    let sport = data.sports.findLast(s => s.name === sportName);
//    console.log('sport: ');
//    console.log(JSON.stringify(sport, null, 2));
    if(!sport){
      /* sport is new */
      data.sports.push({ name: sportName, tournaments: [] });
      sport = data.sports.findLast(s => s.name === sportName);
    }
//    console.log('sport: ');
//    console.log(JSON.stringify(sport, null, 2));

    // get tournament
    selector = "#breadcrumbs > div:nth-child(3) > a";
    el = await page.waitForSelector(selector);
    let tournamentName = await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el);
    mapping = tournamentNameMapping.mapping.find( m => m.specificName === tournamentName);
    if(mapping){
      tournamentName = tournamentNameMap[mapping.globalID];
    } else{
      log.write(`Failure! tournamentName Mapping of '${tournamentName}' does not exist in ${tournamentNameMappingPath}\n`);
      return;
    }
//    console.log('>>>>>>>>>>>>>>> scraped tournamentname: ' + tournamentName);
    let tournament = sport.tournaments.findLast(t => t.name === tournamentName );
    if(!tournament){
      /* tournament is new */
      sport.tournaments.push({ name: tournamentName, matches: [] });
      tournament = sport.tournaments.findLast(t => t.name === tournamentName);
    }
//    console.log('tournament: ');
//    console.log(JSON.stringify(tournament, null, 2));

    // get teamHome, teamAway, datetime, mode
    selector = "div.main-market__home-team > div";
    el = await page.waitForSelector(selector);
    const teamHome = stripTeamName(await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el));
//    console.log('>>>>>>>>>>>>>>> scraped teamHome: ' + teamHome);
    selector = "div.main-market__away-team > div";
    el = await page.waitForSelector(selector);
    const teamAway = stripTeamName(await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el));
//    console.log('>>>>>>>>>>>>>>> scraped teamAway: ' + teamAway);
    selector = "div.match-header__date";
    el = await page.waitForSelector(selector);
    const datetime = convDatetimeToISO(await page.evaluate( e => e.textContent.replace(/\u00a0/g, '\u0020').trim(), el));
//    console.log('>>>>>>>>>>>>>>> scraped datetime: ' + datetime);
    // selector = "div.match-header__bo";
    // el = await page.waitForSelector(selector);
    // const mode = await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el);
//    console.log('>>>>>>>>>>>>>>> scraped mode: ' + mode);
    let match = tournament.matches.findLast(m =>
        m.teamHome === teamHome &&
        m.teamAway === teamAway &&
        m.datetime === datetime
    )
    if(!match){
      /* tournament is new */
      tournament.matches.push({ 
        teamHome: teamHome,
        teamAway: teamAway,
        datetime: datetime,
        urls: [],
        markets: []
      });
      match = tournament.matches.findLast(m =>
          m.teamHome === teamHome &&
          m.teamAway === teamAway &&
          m.datetime === datetime
      );
    }
    match.urls.push({book: 'Thunderpick', url: url});
//    console.log('match: ');
//    console.log(JSON.stringify(match, null, 2));

    // GET ALL THE MARKETS > ODDS > COEFS FOR THIS MATCH
      // get the Match Winner market
        // get the coefHome
    let marketName = 'Match Winner';
    mapping = marketNameMapping.mapping.find( m => m.specificName === marketName);
    if(mapping){
      marketName = marketNameMap[mapping.globalID];
    } else{
      log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
    }
    selector = 'button.main-market__left-odds > span';
    el = await page.waitForSelector(selector);
    const coefHome = await page.evaluate(e => parseFloat(e.textContent), el);
//    console.log('>>>>>>>>>>>>>>> scraped coefHome: ' + coefHome);
    let market = match.markets.findLast(m => m.name === marketName);
    if(!market){
      match.markets.push({name: marketName, odds: []});
      market = match.markets.findLast(m => m.name === marketName);
    }
//    console.log('market: ');
//    console.log(JSON.stringify(market, null, 2));
    let odd = market.odds.findLast(o => o.name === teamHome);
    if(!odd){
      market.odds.push({name: teamHome, coefs: []});
      odd = market.odds.findLast(o => o.name === teamHome);
    }
//    console.log('odd: ');
//    console.log(JSON.stringify(odd, null, 2));
    let coef = odd.coefs.findLast(c => c.book === 'Thunderpick');
    if(!coef){
      odd.coefs.push({book: 'Thunderpick', value: coefHome});
    } else{
      coef.coef = coefHome;
    }
//    console.log('coef: ');
//    console.log(JSON.stringify(coef, null, 2));
        // get the coefAway
    selector = 'button.main-market__right-odds > span';
    el = await page.waitForSelector(selector);
    const coefAway = await page.evaluate(e => parseFloat(e.textContent), el);
//    console.log('>>>>>>>>>>>>>>> scraped coefAway: ' + coefAway);
    odd = market.odds.findLast(o => o.name === teamAway);
    if(!odd){
      market.odds.push({name: teamAway, coefs: []});
      odd = market.odds.findLast(o => o.name === teamAway);
    }
//    console.log('odd: ');
//    console.log(JSON.stringify(odd, null, 2));
    coef = odd.coefs.findLast(c => c.book === 'Thunderpick');
    if(!coef){
      odd.coefs.push({book: 'Thunderpick', value: coefAway});
    } else{
      coef.coef = coefAway;
    }
//    console.log('coef: ');
//    console.log(JSON.stringify(coef, null, 2));
      // get all the other markets
    selector = 'div.market-accordion';
    await page.waitForSelector(selector);
    const marketHandles = await page.$$(selector);
    for(const marketHandle of marketHandles){

      selector = 'div.market-accordion__market-name';
      marketName = await marketHandle.$eval(selector, e => e.textContent);
      mapping = marketNameMapping.mapping.find( m => m.specificName === marketName);
      if(mapping){
        marketName = marketNameMap[mapping.globalID];
      } else{
        log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
      }
//      console.log('>>>>>>>>>>>>>>> scraped marketName: ' + marketName);
      market = match.markets.findLast(m => m.name === marketName);
      if(!market){
        match.markets.push({name: marketName, odds: []});
        market = match.markets.findLast(m => m.name === marketName);
      }
//      console.log('market: ');
//      console.log(JSON.stringify(market, null, 2));

      selector = 'div.market-row';
      const oddHandles = await marketHandle.$$(selector);
//      console.log(`$$${selector} length: ${oddHandles.length}`);
      if(oddHandles.length >= 2){
        selector = 'div.market-row__team-name';
        const teamPrefix = await oddHandles[0].$$eval(selector, es => (es.map(e => e.textContent)));
//        console.log(`$$eval${selector} length: ${teamPrefix.length}`);
//        console.log('>>>>>>>>>>>>>>> scraped teamPrefix[0]: ' + teamPrefix[0]);
//        console.log('>>>>>>>>>>>>>>> scraped teamPrefix[1]: ' + teamPrefix[1]);
        selector = 'button.odds-button';
        for(let i = 1; i < oddHandles.length; i++){
          const buttonHandles = await oddHandles[i].$$(selector);
//          console.log(`$$eval${selector} length: ${buttonHandles.length}`);
          for(let j = 0; j < buttonHandles.length; j++){
            const teamSufix = await buttonHandles[j].$eval('div.odds-button__name', e => e.textContent);
            let oddName = teamPrefix[j] ? `${teamPrefix[j]} ${teamSufix}` : teamSufix;
            oddName = stripTeamName(oddName);
            odd = market.odds.findLast(o => o.name === oddName);
//            console.log('>>>>>>>>>>>>>>> scraped oddName: ' + oddName);
            if(!odd){
              market.odds.push({name: oddName, coefs: []})
              odd = market.odds.findLast(o => o.name === oddName);
            }
            let value;
            try{
              value = await buttonHandles[j].$eval('span.odds-button__odds', e => parseFloat(e.textContent));
            } catch(error){
//              console.log('This odd has no value (the market could be locked)');
              value = null;
            }
//            console.log('>>>>>>>>>>>>>>> scraped value: ' + value);
            coef = odd.coefs.findLast(c => c.book === 'Thunderpick');
            if(!coef){
              odd.coefs.push({book: 'Thunderpick', value: value});
            }
//            console.log('market: ');
//            console.log(JSON.stringify(market, null, 2));
          }
        }
      } else{
        log.write(`Critical Failure! I have less than 2 odds for market ${marketName}\n`);
        return -1;
      }
    }

    log.write(`Success! scraping from ${url} succeeded\n`);
    return 0;    

  } catch (error){
    log.write(`Critical Failure! scraping a match from ${url}`);
    return -1;
  } finally{
    await browser?.close();
    await promisify(log.end).bind(log);
  }
  
}